def load_config(defaults: dict, env: dict) -> dict:
    """Return a copy of ``defaults`` with matching ``APP_`` overrides.

    Environment values are converted using the type of the corresponding
    default value.  Only keys already present in ``defaults`` are considered.
    """
    cfg = dict(defaults)

    for name, value in env.items():
        if not name.startswith("APP_"):
            continue

        key = name[4:].lower()
        if key not in defaults:
            continue

        default = defaults[key]
        if isinstance(default, bool):
            normalized = str(value).strip().lower()
            if normalized in {"1", "true", "yes", "on"}:
                converted = True
            elif normalized in {"0", "false", "no", "off"}:
                converted = False
            else:
                raise ValueError(f"invalid boolean value for {name}: {value!r}")
        elif isinstance(default, int):
            converted = int(value)
        elif isinstance(default, float):
            converted = float(value)
        elif isinstance(default, str):
            converted = str(value)
        else:
            # The supported configuration types are int, float, bool, and
            # str.  Leave unsupported defaults untouched rather than making
            # an arbitrary conversion.
            continue

        cfg[key] = converted

    return cfg
